import React, { useState } from 'react'
import axios from 'axios'

export const ItemLookupScreen = () => {
  const [itemId, setItemId] = useState('')
  const [itemDetails, setItemDetails] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const API_BASE_URL = process.env.REACT_APP_API_URL || 'https://celerant-backend.agreeablemeadow-3f37c30d.westus2.azurecontainerapps.io'

  const lookupItem = async () => {
    if (!itemId.trim()) {
      setError('Please enter an Item ID')
      return
    }

    setLoading(true)
    setError(null)
    setItemDetails(null)

    try {
      const response = await axios.get(`${API_BASE_URL}/api/items/${itemId}`)
      setItemDetails(response.data)
    } catch (err: any) {
      setError(
        err.response?.data?.detail || 
        err.message || 
        'Failed to lookup item'
      )
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="screen-container">
      <div className="screen-header">
        <h1 className="screen-title">Item Lookup</h1>
      </div>

      {error && (
        <div className="alert alert-error">
          {error}
        </div>
      )}

      <div className="card">
        <div className="card-header">
          <h2 className="card-title">Lookup Item Details</h2>
        </div>
        <div className="card-body">
          <form onSubmit={(e) => {
            e.preventDefault()
            lookupItem()
          }}>
            <div className="form-group">
              <label className="form-label" htmlFor="itemId">
                Item ID / SKU
              </label>
              <input
                type="text"
                id="itemId"
                className="form-control form-control-lg"
                value={itemId}
                onChange={(e) => setItemId(e.target.value)}
                placeholder="Enter Item ID to lookup"
                required
                autoFocus
              />
            </div>

            <button
              type="submit"
              className="btn-primary"
              disabled={loading}
            >
              {loading ? 'Looking up...' : 'Lookup Item'}
            </button>
          </form>
        </div>
      </div>

      {itemDetails && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Item Details</h2>
          </div>
          <div className="card-body">
            <div className="row">
              <div className="col-md-6">
                <p><strong>Item ID:</strong> {itemDetails.item_id}</p>
                <p><strong>Description:</strong> {itemDetails.description}</p>
                <p><strong>Vendor:</strong> {itemDetails.vendor_name}</p>
                <p><strong>Category:</strong> {itemDetails.category}</p>
                <p><strong>Unit Cost:</strong> ${parseFloat(itemDetails.unit_cost || 0).toFixed(2)}</p>
              </div>
              <div className="col-md-6">
                <p><strong>Current Stock:</strong> {itemDetails.current_stock}</p>
                <p><strong>On Order:</strong> {itemDetails.on_order}</p>
                <p><strong>Available:</strong> {itemDetails.available_quantity}</p>
                <p><strong>Reorder Point:</strong> {itemDetails.reorder_point}</p>
                <p><strong>Lead Time:</strong> {itemDetails.lead_time} days</p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
